args.sparql:
SELECT DISTINCT ?father ?fatherLabel WHERE {
  { dbr:Prince_Moriyoshi dbp:father ?father }
  UNION
  { dbr:Prince_Moriyoshi dbo:parent ?father }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER (lang(?fatherLabel) = "en") }
}

SELECT DISTINCT ?place ?placeLabel WHERE {
  { dbr:Emperor_Go-Daigo dbp:birthPlace ?place }
  UNION
  { dbr:Emperor_Go-Daigo dbo:birthPlace ?place }
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = "en") }
}

SELECT DISTINCT ?father ?fatherLabel ?birthPlace ?birthPlaceLabel WHERE {
  { dbr:Prince_Moriyoshi dbp:father ?father }
  UNION
  { dbr:Prince_Moriyoshi dbo:parent ?father }
  {
    { ?father dbp:birthPlace ?birthPlace }
    UNION
    { ?father dbo:birthPlace ?birthPlace }
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel) = "en") }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = "en") }
}

